  // ------------------------------------------------------------ oficina: G-buffer, oclusão e recorte
  const VS = `varying vec3 vN,vP,vW;varying vec2 vU;void main(){vP=position;vU=uv;vec4 w=modelMatrix*vec4(position,1.);vW=w.xyz;vN=normalize(mat3(modelMatrix)*normal);vN=normalize(inverse(transpose(mat3(modelMatrix)))*normal);gl_Position=projectionMatrix*viewMatrix*w;}`;
  const FS = `precision highp float;varying vec3 vN,vP,vW;varying vec2 vU;uniform vec3 c1,c2;uniform float asp,metal,esc,bmp,alfa;uniform int tex;uniform bool temMapa;uniform sampler2D mapa;
  layout(location=0) out vec4 o0;layout(location=1) out vec4 o1;layout(location=2) out vec4 o2;
  float h3(vec3 p){p=fract(p*.3183+.1);p*=17.;return fract(p.x*p.y*p.z*(p.x+p.y+p.z));}
  float ns(vec3 p){vec3 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(mix(h3(i),h3(i+vec3(1,0,0)),f.x),mix(h3(i+vec3(0,1,0)),h3(i+vec3(1,1,0)),f.x),f.y),mix(mix(h3(i+vec3(0,0,1)),h3(i+vec3(1,0,1)),f.x),mix(h3(i+vec3(0,1,1)),h3(i+vec3(1,1,1)),f.x),f.y),f.z);}
  float fbm(vec3 p){float a=.5,s=0.;for(int i=0;i<5;i++){s+=a*ns(p);p=p*2.03+7.1;a*=.5;}return s;}
  float worley(vec3 p){vec3 i=floor(p),f=fract(p);float d=9.;for(int x=-1;x<2;x++)for(int y=-1;y<2;y++)for(int z=-1;z<2;z++){vec3 o=vec3(x,y,z),q=o+vec3(h3(i+o),h3(i+o+31.),h3(i+o+57.))-f;d=min(d,dot(q,q));}return sqrt(d);}
  void main(){vec3 n=normalize(gl_FrontFacing?vN:-vN),p=vP*esc,c=c1;float r=asp,h=0.,a=alfa,rr=length(vP.xz);
   if(tex==1){float v=fbm(vec3(p.x*2.2,p.y*.22,p.z*2.2)),g=ns(vec3(p.x*16.,p.y*.7,p.z*16.)),an=sin(v*24.)*.5+.5;c=mix(c1,c2,clamp(an*.55+g*.4,0.,1.));c*=.86+.28*fbm(p*.7);h=(g*.5+an*.5)*.035;r+=g*.14-.05;}
   else if(tex==2){vec2 q=p.xy*9.;float w=sin(q.x*3.14)*sin(q.y*3.14);h=w*.03;c=mix(c1,c2,.5-.5*w)*(.9+.2*fbm(p*2.)+.08*w);}
   else if(tex==3){float f=fbm(p*1.1),f2=fbm(p*9.);c=mix(c1,c2,smoothstep(.42,.75,f)*.8)*(.95+.1*f2);h=f2*.012+fbm(p*.8)*.05;}
   else if(tex==4){float f=ns(vec3(vW.x*26.,vW.y*1.2,vW.z*9.));c*=.92+.14*f;r+=f*.12-.03;h=f*.006;}
   else if(tex==5){float w=worley(p*7.5);h=w*.022;c*=.84+.28*w;c*=.9+.25*fbm(p*1.2);}
   else if(tex==6){float f=fbm(p*1.4),s=smoothstep(.62,.7,ns(p*9.));c=mix(c1,c2,smoothstep(.35,.7,f))*(1.-.12*s);h=f*.035;}
   else if(tex==7){float f=fbm(p*1.3+3.),s=ns(vec3(p.x*18.,p.y*18.,p.z*18.));c=mix(c1,c2,smoothstep(.46,.72,f)*.75);r+=smoothstep(.45,.7,f)*.28+s*.06;h=f*.05;}
   else if(tex==8){float f=ns(p*22.);r+=f*.05;h=f*.002;c*=.97+.06*fbm(p*2.);}
   else if(tex==9){float at=atan(vP.z,vP.x),s=sin((p.y*5.+at*1.2+p.x*3.)*3.14);h=s*.07;c*=.82+.22*s+.15*ns(p*14.);}
   else if(tex==10){float f=fbm(p*.9);c*=.95+.08*f;h=f*.04;}
   if(temMapa){vec4 t=texture2D(mapa,vU);c=t.rgb;a=t.a;if(a<.02)discard;}
   if(bmp>0.&&h!=0.){vec3 dx=dFdx(vW),dy=dFdy(vW);float hx=dFdx(h)*bmp,hy=dFdy(h)*bmp;vec3 r1=cross(dy,n),r2=cross(n,dx);float d=dot(dx,r1);vec3 gr=sign(d)*(hx*r1+hy*r2);n=normalize(abs(d)*n-gr);}
   if(alfa<.99){float fr=pow(1.-clamp(n.z,0.,1.),1.6);a=mix(alfa,min(1.,alfa+.5),fr);c=mix(c,c*1.15,fr);}
   o0=vec4(c*a,a);o1=vec4(n,1.);o2=vec4(clamp(r,.02,1.),metal,vW.z+10.,1.);}`;
  function material(m) { return new T.ShaderMaterial({ vertexShader: VS, fragmentShader: FS, glslVersion: T.GLSL3, side: m.alfa < .99 ? T.FrontSide : T.DoubleSide, transparent: true, depthWrite: !m.mapa, depthTest: true, blending: T.CustomBlending, blendSrc: T.OneFactor, blendDst: T.OneMinusSrcAlphaFactor, blendEquation: T.AddEquation, polygonOffset: !!m.mapa, polygonOffsetFactor: -2, polygonOffsetUnits: -2, uniforms: { c1: { value: m.cor }, c2: { value: m.cor2 }, asp: { value: m.asp }, metal: { value: m.metal }, esc: { value: m.escala }, bmp: { value: m.bump }, alfa: { value: m.alfa }, tex: { value: m.tex }, temMapa: { value: !!m.mapa }, mapa: { value: m.mapa } } }); }
  function montar(o) {
    g = new T.Group(); sem = 1; o.f(); g.updateMatrixWorld(true);
    g.traverse(k => { if (k.isMesh) { k.material = material(k.m); k.renderOrder = k.m.mapa ? 2 : k.m.alfa < .99 ? 1 : 0; } });
    const c = new T.Box3().setFromObject(g, true); return { g, c };
  }
  // passa tudo para os dois retratos finais
  const FIM = `precision highp float;varying vec2 vU;uniform sampler2D ta,tn,tm;uniform vec2 px;uniform float u2px,zmin;uniform int modo;layout(location=0) out vec4 o;
  float alt(vec2 u){vec4 k=texture2D(tm,u);return k.a<.5?0.:max(0.,k.b/k.a-10.-zmin);}
  void main(){vec4 A=texture2D(ta,vU),N=texture2D(tn,vU),M=texture2D(tm,vU);float al=A.a;
   if(M.a<.02){float bd=1e9;for(int i=0;i<24;i++){float an=float(i)*.2618;for(int k=1;k<7;k++){vec2 q=vU+vec2(cos(an),sin(an))*px*float(k)*2.;vec4 mm=texture2D(tm,q);if(mm.a>.5&&float(k)<bd){bd=float(k);A=texture2D(ta,q);N=texture2D(tn,q);M=mm;}}}
    if(M.a<.02){o=modo==0?vec4(0.):vec4(.5,.5,.4,1.);return;}}
   vec3 n=normalize(N.xyz);float rr=M.r/max(M.a,.01),me=M.g/max(M.a,.01);
   if(modo==0){float h=alt(vU),oc=0.,w=0.;for(int i=0;i<20;i++){float an=float(i)*.31416+.1,mx=0.;vec2 d=vec2(cos(an),sin(an));for(int k=1;k<=12;k++){float s=float(k)/12.;s=s*s*2.2;float dh=alt(vU+d*s*u2px)-h;mx=max(mx,atan(dh-.02,s));}oc+=sin(max(0.,mx));w+=1.;}
     float ao=1.-.85*oc/w;ao=clamp(ao,.12,1.);
     vec2 e=px*2.2;vec3 nx=texture2D(tn,vU+vec2(e.x,0)).xyz-texture2D(tn,vU-vec2(e.x,0)).xyz,ny=texture2D(tn,vU+vec2(0,e.y)).xyz-texture2D(tn,vU-vec2(0,e.y)).xyz;float dv=clamp(nx.x+ny.y,-1.,1.);
     vec3 c=A.rgb/max(A.a,.001);c*=mix(ao,1.,.0);c*=1.+.22*max(dv,0.)-.3*max(-dv,0.);c=pow(clamp(c,0.,1.),vec3(1./2.2));o=vec4(c,al);}
   else {o=vec4(n.xy*.5+.5,me>.5?.52+.48*rr:.48*rr,1.);}}`;
  function desenhar(R, o, K) {
    // devolve { w, h (px), cor, nor, hz }: dois canvas do tamanho pedido
    const { g: G, c } = montar(o), M = 14, w = Math.ceil((c.max.x - c.min.x) * K) + 2 * M, h = Math.ceil((c.max.y - c.min.y) * K) + 2 * M, S = 3, W = w * S, H = h * S, cx0 = (c.min.x + c.max.x) / 2, cy0 = (c.min.y + c.max.y) / 2;
    const cam = new T.OrthographicCamera(-w / 2 / K, w / 2 / K, h / 2 / K, -h / 2 / K, .1, 100); cam.position.set(cx0, cy0, 50); cam.lookAt(cx0, cy0, 0); cam.up.set(0, 1, 0);
    const rt = new T.WebGLRenderTarget(W, H, { count: 3, type: T.FloatType, minFilter: T.NearestFilter, magFilter: T.NearestFilter });
    const cena = new T.Scene(); cena.add(G); R.setRenderTarget(rt); R.setClearColor(0, 0); R.clear(); R.render(cena, cam); R.setRenderTarget(null);
    const q = new T.Mesh(new T.PlaneGeometry(2, 2)), cf = new T.Scene(), camf = new T.OrthographicCamera(-1, 1, 1, -1, 0, 1); cf.add(q);
    const uni = { ta: { value: rt.textures[0] }, tn: { value: rt.textures[1] }, tm: { value: rt.textures[2] }, px: { value: V2(1 / W, 1 / H) }, u2px: { value: K * S / W }, zmin: { value: c.min.z }, modo: { value: 0 } };
    const mk = modo => { q.material = new T.ShaderMaterial({ vertexShader: 'varying vec2 vU;void main(){vU=uv;gl_Position=vec4(position.xy,0.,1.);}', fragmentShader: FIM.replaceAll('alt(vU+d*s*u2px)', 'alt(vU+d*s*u2)').replace('uniform float u2px,zmin;', 'uniform vec2 u2;uniform float zmin;'), glslVersion: T.GLSL3, uniforms: { ...uni, modo: { value: modo }, u2: { value: V2(K * S / W, K * S / H) } }, depthTest: false }); R.setSize(W, H, false); R.setClearColor(0, 0); R.clear(); R.render(cf, camf); const d = document.createElement('canvas'); d.width = w; d.height = h; const x = d.getContext('2d'); x.imageSmoothingQuality = 'high'; x.drawImage(R.domElement, 0, 0, w, h); return d; };
    const cor = mk(0), nor = mk(1); rt.dispose(); G.traverse(k => k.geometry && k.geometry.dispose());
    return { w, h, cor, nor, alt: c.max.z - c.min.z };
  }
